<template><ElSpace direction="vertical" fill class="v1-page" :size="20">
 <ElSpace class="v1-spread"><ElSpace><ElTag type="warning">四图轮播 · 模拟监控</ElTag><ElTag type="success">JPEG 实时快照</ElTag><ElTag>4 张照片</ElTag><ElTag>{{camera.paused?'已暂停':camera.interval_s+' 秒切换'}}</ElTag></ElSpace><ElSpace><ElButton :loading="loading" @click="refreshSnapshot(true)">立即刷新</ElButton><ElButton @click="toggle">{{camera.paused?'继续轮播':'暂停轮播'}}</ElButton><ElButton type="primary" @click="edit">轮播设置</ElButton></ElSpace></ElSpace>
 <ElImage :src="displayURL" alt="四张照片循环播放的 JPEG 实时监控" fit="contain" style="width:100%;height:360px"><template #placeholder><ElSkeleton animated><template #template><ElSkeletonItem variant="image" style="width:100%;height:360px" /></template></ElSkeleton></template><template #error><ElEmpty description="JPEG 画面未连接" /></template></ElImage>
 <ElDescriptions :column="1" border><ElDescriptionsItem label="MJPEG 地址"><ElSpace direction="vertical" fill class="v1-dialog-stack"><ElInput class="v1-copy-field" :model-value="streamURL" readonly aria-label="模拟 MJPEG 地址"><template #append><ElButton @click="copy(streamURL)">复制</ElButton></template></ElInput><ElTag>天枢选择 MJPEG</ElTag></ElSpace></ElDescriptionsItem><ElDescriptionsItem label="快照地址"><ElSpace direction="vertical" fill class="v1-dialog-stack"><ElInput class="v1-copy-field" :model-value="snapshotURL" readonly aria-label="模拟快照地址"><template #append><ElButton @click="copy(snapshotURL)">复制</ElButton></template></ElInput><ElTag>天枢选择 JPEG</ElTag></ElSpace></ElDescriptionsItem></ElDescriptions>
 <ElRow :gutter="16"><ElCol v-for="photo in camera.photos||[]" :key="photo.index" :xs="12" :md="6"><ElCard shadow="never"><template #header><ElSpace><strong>照片 {{photo.index}}</strong><ElTag>{{photo.custom?'已替换':'预置模拟图'}}</ElTag></ElSpace></template><ElImage :src="photoURL(photo)" :alt="'轮播照片 '+photo.index" fit="contain" style="width:100%;height:130px" /><ElTooltip content="JPEG，单张不超过3MB；照片只存本机，监控接口可被本机程序读取"><ElUpload :key="photo.index+'-'+photo.revision" :auto-upload="false" accept="image/jpeg" :show-file-list="false" :on-change="file=>upload(photo.index,file)" :disabled="!!uploading"><ElButton class="v1-gap" :loading="uploading===photo.index">替换照片</ElButton></ElUpload></ElTooltip></ElCard></ElCol></ElRow>
 </ElSpace><ElDrawer v-model="open" title="模拟监控轮播设置" direction="rtl" size="min(520px,100vw)" destroy-on-close :close-on-click-modal="false"><ArtForm v-model="draft" :items="fields" :span="24" label-position="top" :show-submit="false" :show-reset="false" /><ElAlert v-if="error" :title="error" type="error" :closable="false" /><template #footer><ElButton @click="open=false">取消</ElButton><ElButton type="primary" :loading="saving" @click="save">保存设置</ElButton></template></ElDrawer></template>
<script setup>
import {ref,onMounted,onBeforeUnmount} from 'vue';import {ElMessage} from 'element-plus';
const props=defineProps({camera:{type:Object,default:()=>({interval_s:5,paused:false,photos:[]})},request:Function});const emit=defineEmits(['refresh']);const open=ref(false),draft=ref({}),saving=ref(false),uploading=ref(0),error=ref(''),displayURL=ref(''),loading=ref(false);const streamURL=location.origin+'/mock/camera/stream.mjpeg',snapshotURL=location.origin+'/mock/camera/snapshot.jpg';const fields=[{key:'interval_s',label:'每张停留 / 秒',type:'number',props:{min:1,max:60,precision:0}},{key:'paused',label:'暂停轮播',type:'switch'}];let snapshotTimer=0,requestNumber=0;
function currentSnapshotURL(){const u=new URL(snapshotURL);u.searchParams.set('_t',Date.now());return u.href}
function refreshSnapshot(manual=false){if(document.hidden&&!manual)return;const number=++requestNumber,url=currentSnapshotURL();loading.value=manual;const image=new Image();image.onload=()=>{if(number===requestNumber)displayURL.value=url;loading.value=false};image.onerror=()=>{if(number===requestNumber&&manual)ElMessage.error('JPEG 画面连接失败');loading.value=false};image.src=url}
function visibility(){if(!document.hidden)refreshSnapshot()}
onMounted(()=>{refreshSnapshot();snapshotTimer=window.setInterval(refreshSnapshot,1000);document.addEventListener('visibilitychange',visibility)});onBeforeUnmount(()=>{clearInterval(snapshotTimer);document.removeEventListener('visibilitychange',visibility);requestNumber++});
function photoURL(p){return location.origin+'/mock/camera/frames/'+p.index+'.jpg?v='+p.revision}
function edit(){draft.value={interval_s:props.camera.interval_s,paused:props.camera.paused};error.value='';open.value=true}
async function save(){saving.value=true;error.value='';try{await props.request('camera-settings',draft.value);open.value=false;emit('refresh');ElMessage.success('轮播设置已保存')}catch(e){error.value=e.message}finally{saving.value=false}}
async function toggle(){try{await props.request('camera-settings',{interval_s:props.camera.interval_s,paused:!props.camera.paused});emit('refresh')}catch(e){ElMessage.error(e.message)}}
async function copy(url){try{await navigator.clipboard.writeText(url);ElMessage.success('监控地址已复制')}catch{ElMessage.error('复制失败，请手动选择复制')}}
async function upload(index,file){if(!file.raw||file.size>3*1024*1024||file.raw.type!=='image/jpeg'){ElMessage.error('请选择3MB以内的 JPEG 照片');return}uploading.value=index;try{const data=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result.split(',')[1]);reader.onerror=()=>reject(Error('照片读取失败'));reader.readAsDataURL(file.raw)});await props.request('camera-photo',{index,data});emit('refresh');ElMessage.success('模拟照片已替换')}catch(e){ElMessage.error(e.message)}finally{uploading.value=0}}
</script>
